mapper.select:
select a.FINPROD_ID finprodId, a.FINPROD_MARKET_ID finprodMarketId, a.FINPROD_ABBR finprodAbbr, b.TRM_FUND_TYPE trmFundType, b.ETF_TYPE etfType, a.TRADE_MARKET tradeMarket, c.CUSTOMER_NAME manager, b.BONUS_TYPE bonusType, a.IDATE idate, (CASE WHEN b.PUR_SPEED is not null THEN 'T+'||b.PUR_SPEED ELSE '' END) purSpeed, (CASE WHEN b.RED_SPEED is not null THEN 'T+'||b.RED_SPEED ELSE '' END) redSpeed, a.VDATE vdate from FIN_PRODUCT a left join FIN_PRODUCT_ADD b on b.FINPROD_ID = a.FINPROD_ID left join MST_CUSTOMER_INFO c on c.CUSTOMER_ID = a.MANAGER where a.TRADE_MARKET in (#{TRADE_PLACE_03,jdbcType=VARCHAR},#{TRADE_PLACE_04,jdbcType=VARCHAR}) and a.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}
and a.FINPROD_MARKET_ID like CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
and b.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}
and b.ETF_TYPE = #{etfType,jdbcType=VARCHAR}
and a.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
and a.MANAGER = #{manager,jdbcType=VARCHAR}
and a.VDATE >= to_date(#{startDate},'yyyy-MM-dd')
and a.VDATE <= to_date(#{endDate},'yyyy-MM-dd')
